const out = [];
const ts = (t) => {
  if (t == null || t === '') return '';
  const n = Number(t);
  if (!Number.isFinite(n)) return '';
  return new Date(String(Math.trunc(n)).length > 10 ? n : n * 1000).toISOString();
};
const tipoDe = (m, field, contaId) => {
  if (field === 'message_edit' || m.message_edit) return 'edit';
  if (field === 'message_reactions' || m.reaction) return 'reaction';
  if (field === 'messaging_seen' || m.read) return 'read';
  if (field === 'messaging_postbacks' || m.postback) return 'postback';
  if (field === 'messaging_referral' || m.referral) return 'referral';
  if (m.message) {
    const daPropriaConta = contaId && m.sender?.id != null && String(m.sender.id) === contaId;
    return (m.message.is_echo || daPropriaConta) ? 'echo' : 'message';
  }
  return field ? 'change_' + field : 'outro';
};
const linha = (b, e, m, field, extraPayload) => {
  const contaId = e.id != null ? String(e.id) : '';
  return { json: {
    object: b.object || '',
    ig_conta_id: contaId,
    remetente_id: m.sender?.id != null ? String(m.sender.id) : '',
    destinatario_id: m.recipient?.id != null ? String(m.recipient.id) : '',
    tipo: tipoDe(m, field, contaId),
    mid: m.message?.mid || m.message_edit?.mid || '',
    texto: m.message?.text || m.message_edit?.text || '',
    evento_em: ts(m.timestamp) || ts(e.time),
    payload: JSON.stringify(extraPayload || m)
  }};
};
for (const it of $input.all()) {
  const b = it.json.body || {};
  for (const e of (b.entry || [])) {
    for (const m of (e.messaging || [])) out.push(linha(b, e, m, null));
    for (const m of (e.standby || [])) { const r = linha(b, e, m, null); r.json.tipo = 'standby_' + r.json.tipo; out.push(r); }
    for (const c of (e.changes || [])) {
      const v = (c.value && typeof c.value === 'object') ? c.value : {};
      out.push(linha(b, e, v, c.field || 'desconhecido', c));
    }
  }
}
return out;
